-- Categories (5 Nhóm Ếch)
INSERT INTO categories (id, name, slug, description, icon) VALUES
  (1, 'Ếch Pacman', 'pacman', 'Dòng ếch sừng Nam Mỹ tròn trịa, háu ăn, cực kỳ dễ nuôi cho người mới bắt đầu', '🐸'),
  (2, 'Ếch Cây', 'tree-frog', 'Các loài ếch leo trèo duyên dáng, màu sắc rực rỡ, thích hợp bể terrarium và bán cạn', '🌿'),
  (3, 'Ếch Phi Tiêu Độc', 'dart-frog', 'Đá quý sống của rừng nhiệt đới, sặc sỡ quyến rũ, sinh sản nhân tạo 100% không độc', '💎'),
  (4, 'Ếch Bò & Thủy Sinh', 'bullfrog', 'Các loài ếch ngoại cỡ dũng mãnh và loài ếch thủy sinh độc đáo', '👑'),
  (5, 'Ếch Kỳ Lạ & Đặc Hữu', 'exotic', 'Những loài ếch hình thù độc đáo, ngụy trang đỉnh cao và báu vật ếch rêu Việt Nam', '✨');

-- Products (26 Species)
INSERT INTO products (
  id, category_id, slug, name, scientific_name, morph, price, original_price,
  size_stage, lifespan, difficulty, habitat_type, temperature, humidity, diet,
  description, care_guide, health_status, image, gallery_images_json, stock, is_featured
) VALUES
  (1, 1, 'pacman-green', 'Ếch Pacman Xanh (Green)', 'Ceratophrys cranwelli', 'Green Normal', 180000, 220000, 'Baby (3 - 4cm)', '8 - 12 năm', 'Dễ', 'terrestrial', '24 - 28°C', '70 - 80%', 'Cá mồi nhỏ, dế, sâu canxi, cám Pac Attack', 'Dòng Pacman nguyên bản với sắc xanh cốm tự nhiên phối đốm nâu đất. Cơ thể tròn ủng như quả bóng, miệng rộng chiếm nửa thân hình cực kỳ háu ăn và ngộ nghĩnh.', 'Nuôi hộp nhựa thông hơi, lót mút xốp ngập 1/3 nước sạch hoặc dớn ẩm. 2-3 ngày cho ăn 1 lần, bổ sung bột canxi D3 mỗi tuần.', 'Bao sống 100% khi nhận hàng, đã thuần cám và dế, ăn khỏe không dị tật', '/images/frogs/pacman-green.jpg', '["/images/frogs/pacman-green.jpg", "/images/frogs/pacman-samurai.jpg"]', 25, 1),
  (2, 1, 'pacman-albino', 'Ếch Pacman Vàng Bạch Tạng (Albino)', 'Ceratophrys cranwelli', 'Albino Yellow', 260000, 300000, 'Baby (3 - 4cm)', '8 - 12 năm', 'Dễ', 'terrestrial', '24 - 28°C', '70 - 80%', 'Cá chép mồi, dế mèn, gián dubia, cám viên', 'Đột biến bạch tạng vàng chanh rực rỡ kết hợp cặp mắt đỏ ruby đặc trưng. Là một trong những dòng ếch cảnh bán chạy và được yêu thích nhất toàn cầu.', 'Tránh ánh nắng mặt trời gắt trực tiếp vì mắt bạch tạng nhạy cảm. Giữ độ ẩm nền ổn định, thay nước sạch định kỳ.', 'Mắt sáng tinh anh, chân tay lực lưỡng, đớp mồi cực nhạy', '/images/frogs/pacman-albino.jpg', '["/images/frogs/pacman-albino.jpg", "/images/frogs/pacman-green.jpg"]', 20, 0),
  (3, 1, 'pacman-samurai', 'Ếch Pacman Samurai Matcha', 'Ceratophrys cranwelli', 'Mutant Samurai Green', 380000, 450000, 'Baby (3.5cm)', '8 - 12 năm', 'Dễ', 'terrestrial', '24 - 28°C', '75 - 85%', 'Cá mồi, dế sữa, gián red runner', 'Morph đột biến cao cấp với màu xanh trà xanh (matcha) mịn màng, ít đốm nâu tạp sắc. Tạo cảm giác thanh thoát, phong thủy may mắn tài lộc.', 'Duy trì độ ẩm bằng bình xịt phun sương mỗi ngày 1 lần. Chuồng nuôi thoáng khí tránh đọng khí độc.', 'Tuyển chọn cá thể màu chuẩn đậm, đã ăn quen mồi gắp', '/images/frogs/pacman-samurai.jpg', '["/images/frogs/pacman-samurai.jpg"]', 15, 0),
  (4, 1, 'pacman-strawberry', 'Ếch Pacman Dâu Tây (Strawberry)', 'Ceratophrys cranwelli', 'Strawberry Morph', 480000, 550000, 'Baby (3 - 4cm)', '8 - 12 năm', 'Dễ', 'terrestrial', '24 - 28°C', '70 - 80%', 'Cá trâm, cá bảy màu, sâu canxi, gián dubia', 'Sắc tố đỏ hồng pha cam pastel ngọt ngào như trái dâu chín mọng. Dòng Pacman đột biến màu ấm rất hiếm và có giá trị thẩm mỹ cao.', 'Nền chuồng sạch sẽ giúp giữ màu da sáng đẹp. Tránh dùng nước máy chứa clo trực tiếp.', 'Được cách ly thuần dưỡng 14 ngày trước khi xuất bán, ăn khỏe', '/images/frogs/pacman-strawberry.jpg', '["/images/frogs/pacman-strawberry.jpg"]', 10, 0),
  (5, 1, 'pacman-super-red', 'Ếch Pacman Cà Chua Đỏ (Super Red)', 'Ceratophrys cranwelli', 'Super Red', 420000, 490000, 'Baby (3.5cm)', '8 - 12 năm', 'Dễ', 'terrestrial', '24 - 28°C', '70 - 80%', 'Dế, trùn huyết đông lạnh, cá mồi', 'Tông màu cam lửa phối đỏ đất cực kỳ bắt mắt, hoa văn vằn sậm tương phản mạnh tạo vẻ dũng mãnh.', 'Nhiệt độ ổn định quanh 26 độ C giúp hệ tiêu hóa của ếch hấp thụ tốt nhất.', 'Khỏe mạnh 100%, bảo hành 7 ngày sau khi nhận', '/images/frogs/pacman-red.jpg', '["/images/frogs/pacman-red.jpg"]', 12, 0),
  (6, 1, 'pacman-amazon-horned', 'Ếch Sừng Amazon Bốn Mắt (Surinam Horned)', 'Ceratophrys cornuta', 'Wild Amazonian', 950000, 1150000, 'Baby (4 - 5cm)', '10 - 15 năm', 'Trung bình', 'terrestrial', '25 - 29°C', '75 - 85%', 'Cá mồi, nhái con, gián dubia', 'Vua của các loài ếch sừng Pacman tự nhiên! Sở hữu đôi sừng nhọn hoắt vươn cao trên mí mắt và miệng ngoác cực đại, hoa văn ngụy trang lá khô Amazon huyền ảo.', 'Thích vùi mình sâu trong dớn ẩm hoặc mùn dừa hữu cơ. Cần môi trường yên tĩnh, tránh làm giật mình.', 'Ếch nhập khẩu F1 khỏe mạnh, sừng đều thẳng tắp, không tật lỗi', '/images/frogs/pacman-amazon.jpg', '["/images/frogs/pacman-amazon.jpg"]', 8, 0),
  (7, 1, 'pacman-fantasy', 'Ếch Sừng Lai Fantasy (Cranwelli x Cornuta)', 'Ceratophrys cranwelli x cornuta', 'Fantasy F1 Hybrid', 620000, 750000, 'Baby (3.5 - 4cm)', '10 - 12 năm', 'Dễ', 'terrestrial', '24 - 28°C', '70 - 80%', 'Dế, gián dubia, cá mồi, cám viên', 'Dòng lai F1 hoàn hảo kết hợp sức ăn trâu bò của Cranwelli và cặp sừng nhọn dũng mãnh của Cornuta. Thân hình vạm vỡ, hoa văn rực rỡ và sức sống cực cao.', 'Chăm sóc dễ dàng như Pacman thường nhưng vóc dáng phát triển to lớn và sừng rõ rệt hơn.', 'Ăn khỏe như vũ bão, sừng nhọn đều hai bên', '/images/frogs/pacman-fantasy.jpg', '["/images/frogs/pacman-fantasy.jpg"]', 14, 0),
  (8, 2, 'tree-red-eyed', 'Ếch Cây Mắt Đỏ (Red-Eyed Tree Frog)', 'Agalychnis callidryas', 'Standard Neotropical', 1150000, 1350000, 'Sub-adult (4 - 5cm)', '5 - 8 năm', 'Trung bình', 'arboreal', '24 - 27°C', '75 - 90%', 'Dế con phủ canxi D3, ruồi giấm, cào cào nhỏ', 'Biểu tượng của rừng mưa nhiệt đới Trung Mỹ. Thân xanh ngọc mướt mát, mạn sườn sọc tím xanh hoàng gia, bàn chân cam neon và đôi mắt đỏ rực ma mị.', 'Yêu cầu bể kính nuôi dạng đứng (Terrarium), có nhiều cành cây, lá rộng ẩm để bám ngủ ban ngày. Phun sương ẩm sáng tối.', 'Đã quen chuồng kính nuôi nhốt, mắt đỏ trong suốt, leo trèo cực lẹ', '/images/frogs/tree-red-eyed.jpg', '["/images/frogs/tree-red-eyed.jpg"]', 6, 1),
  (9, 2, 'tree-whites-dumpy', 'Ếch Cây Lùn Úc (White''s Tree / Dumpy)', 'Ranoidea caerulea', 'Australian Classic', 490000, 580000, 'Baby (3 - 4cm)', '15 - 20 năm', 'Dễ', 'arboreal', '24 - 29°C', '60 - 75%', 'Dế mèn, gián dubia, sâu quy, cám ếch', 'Loài ếch cây thân thiện nhất hành tinh! Khuôn mặt luôn mỉm cười, da nhẵn bóng, tính cách dạn dĩ, có thể ngồi chơi ngoan ngoãn trên ngón tay người nuôi.', 'Rất dễ chăm sóc, chịu được biên độ ẩm rộng hơn các loài ếch khác. Cung cấp máng nước sạch nông và cành lũa leo trèo.', 'Dạn người, ham ăn, không sợ tay người, bảo hành sống trọn vẹn', '/images/frogs/tree-whites-dumpy.jpg', '["/images/frogs/tree-whites-dumpy.jpg"]', 18, 0),
  (10, 2, 'tree-blue-snowflake', 'Ếch Cây Úc Tuyết Xanh (Blue Snowflake)', 'Ranoidea caerulea', 'Blue Snowflake Morph', 890000, 1050000, 'Baby (3.5cm)', '15 - 20 năm', 'Dễ', 'arboreal', '24 - 29°C', '60 - 75%', 'Dế con rắc vitamin, sâu bướm, gián dubia', 'Biến thể tuyệt mỹ của ếch Dumpy: nền da chuyển xanh lam ngọc lam pha chấm đốm trắng li ti như hoa tuyết rải đều trên lưng.', 'Chăm sóc tương tự Dumpy thường, nên cung cấp ánh sáng UVB nhẹ để màu xanh ngọc phát triển tối đa.', 'Hàng tuyển chọn đốm tuyết dày, bảo đảm thuần chủng', '/images/frogs/tree-blue-snowflake-v2.jpg', '["/images/frogs/tree-blue-snowflake-v2.jpg"]', 7, 0),
  (11, 2, 'tree-amazon-milk', 'Ếch Sữa Amazon (Amazon Milk Frog)', 'Trachycephalus resinifictrix', 'Amazon Wild Standard', 790000, 920000, 'Baby (3.5 - 4cm)', '10 - 15 năm', 'Trung bình', 'arboreal', '24 - 28°C', '70 - 85%', 'Dế con phủ canxi, ruồi giấm, gián red runner', 'Loài ếch cây nổi danh Nam Mỹ với họa tiết khoang xanh lam phấn trắng phối đốm nâu chocolate, mắt có chữ thập ma mị. Khi gặp nguy hiểm, da chúng tiết dịch trắng đục như sữa.', 'Bể đứng trồng nhiều cây dây leo bản rộng, có khay nước rộng vì chúng rất thích ngâm mình dưới nước.', 'Khỏe mạnh, đệm mút ngón chân bám kính cực chắc', '/images/frogs/tree-amazon-milk.jpg', '["/images/frogs/tree-amazon-milk.jpg"]', 10, 0),
  (12, 2, 'tree-clown', 'Ếch Hề Cây (Clown Tree Frog)', 'Dendropsophus leucophyllatus', 'Giraffe / Flash Pattern', 850000, 990000, 'Sub-adult (3cm)', '5 - 7 năm', 'Trung bình', 'arboreal', '23 - 27°C', '75 - 90%', 'Ruồi giấm cánh cụt, dế sữa size 1, bướm sáp', 'Được mệnh danh là chú hề của thế giới ếch với mảng màu vàng cam neon uốn lượn trên nền da sô-cô-la đen đậm. Mặt dưới bụng có màu đỏ cam tương phản rực rỡ khi nhảy.', 'Nuôi bể kính bán cạn có nhiều cây thủy sinh, phun sương độ ẩm cao vào ban đêm.', 'Mắt tròn xoe tinh anh, nhảy bám lá thoăn thoắt', '/images/frogs/tree-clown.jpg', '["/images/frogs/tree-clown.jpg"]', 8, 0),
  (13, 2, 'tree-tiger-leg', 'Ếch Khỉ Chân Vằn (Tiger Leg Monkey Frog)', 'Pithecopus hypochondrialis', 'Orange Tiger Pattern', 1050000, 1250000, 'Sub-adult (3.5 - 4cm)', '6 - 10 năm', 'Trung bình', 'arboreal', '24 - 28°C', '65 - 80%', 'Dế con, gián nhỏ, sâu bọ kích thước vừa miệng', 'Loài ếch cực kỳ kỳ lạ: chúng không nhảy như ếch thông thường mà bước đi thận trọng bằng từng ngón tay có khớp đối ngón như loài khỉ! Sườn và đùi trong có vằn hổ cam đen huyền ảo.', 'Chuồng nuôi nhiều cành nhánh thanh mảnh để chúng nắm tay bước đi, thông gió tuyệt hảo.', 'Dáng đi uyển chuyển, phản xạ nắm cành cực tốt', '/images/frogs/tree-tiger-leg.jpg', '["/images/frogs/tree-tiger-leg.jpg"]', 6, 0),
  (14, 2, 'tree-lemur-leaf', 'Ếch Lá Vượn Cáo (Lemur Leaf Frog)', 'Agalychnis lemur', 'Costa Rican Natural', 1450000, 1700000, 'Sub-adult (3 - 3.5cm)', '6 - 8 năm', 'Nâng cao', 'arboreal', '22 - 26°C', '80 - 95%', 'Ruồi giấm hydei, dế con size mini phủ canxi', 'Viên ngọc quý hiếm bậc nhất của Trung Mỹ! Cơ thể mảnh mai như cọng cỏ, đôi mắt to đen láy không mí mắt màng phụ. Ban ngày ngủ có màu xanh nõn chuối ngụy trang, ban đêm đổi màu nâu cánh gián.', 'Cần chuồng nuôi terrarium nhiệt độ mát mẻ (22-26°C), độ ẩm cao và tuyệt đối không để nhiệt độ tăng quá 27°C.', 'Ếch sinh sản captive bred F2 chuẩn gen khỏe mạnh', '/images/frogs/tree-lemur-leaf.jpg', '["/images/frogs/tree-lemur-leaf.jpg"]', 5, 0),
  (15, 3, 'dart-bumblebee', 'Ếch Phi Tiêu Ong Nghệ (Bumblebee Dart Frog)', 'Dendrobates leucomelas', 'Yellow-Banded Standard', 1250000, 1450000, 'Sub-adult (2.5 - 3cm)', '10 - 15 năm', 'Nâng cao', 'terrestrial', '23 - 27°C', '80 - 95%', 'Ruồi giấm cánh cụt, bọ đuôi bật (springtails), mọt đậu', 'Loài phi tiêu độc sọc vàng óng tương phản đen bóng như chú ong vò vẽ. Trong điều kiện sinh sản nhân tạo, ếch hoàn toàn vô hại (không độc do chế độ ăn không kiến rừng). Tiếng kêu líu lo êm tai như tiếng chim hót.', 'Nuôi trong bể Terrarium hệ sinh thái cây thật ẩm ướt, bắt buộc phải có nguồn ruồi giấm sống liên tục.', 'Ếch sinh sản captive bred (F2), hoàn toàn không có độc tố, hoạt bát ban ngày', '/images/frogs/dart-bumblebee.jpg', '["/images/frogs/dart-bumblebee.jpg"]', 5, 0),
  (16, 3, 'dart-azureus', 'Ếch Phi Tiêu Xanh Lam Azureus (Blue Dart)', 'Dendrobates tinctorius', 'Azureus Blue Morph', 1650000, 1850000, 'Sub-adult (3 - 3.5cm)', '10 - 15 năm', 'Nâng cao', 'terrestrial', '22 - 26°C', '85 - 95%', 'Ruồi giấm không cánh, bọ đuôi bật, mọt cám nhỏ', 'Nữ hoàng của các loài ếch phi tiêu! Sở hữu sắc xanh lam thiên thanh kỳ ảo với đốm đen huyền bí. Rất bạo dạn, năng động sục sạo tìm mồi khắp bể bán cạn ban ngày.', 'Cần hệ thống phun sương tự động hoặc xịt ẩm 2-3 lần/ngày. Nhiệt độ không quá 28°C.', 'Màu xanh đậm nét, cơ thể đẫy đà, sống hòa thuận theo cặp hoặc bầy', '/images/frogs/dart-azureus.jpg', '["/images/frogs/dart-azureus.jpg"]', 4, 1),
  (17, 3, 'dart-tinctorius-cobalt', 'Ếch Phi Tiêu Nhuộm Cobalt (Dyeing Dart)', 'Dendrobates tinctorius', 'Cobalt Morph', 1550000, 1750000, 'Sub-adult (3.5cm)', '10 - 15 năm', 'Nâng cao', 'terrestrial', '22 - 26°C', '80 - 95%', 'Ruồi giấm không cánh, bọ đuôi bật', 'Morph Cobalt sở hữu chiếc lưng màu vàng hoàng gia rực rỡ tương phản chân màu xanh lam cobalt đậm đà. Là một trong những dòng phi tiêu cỡ lớn, dạn người và cực kỳ bắt mắt.', 'Nuôi trong bể bán cạn terrarium có rêu thật, khúc lũa ẩm và lá cây bản rộng.', 'Vóc dáng vạm vỡ, ăn mồi lia lịa ngay trước mặt người nuôi', '/images/frogs/dart-tinctorius-cobalt.jpg', '["/images/frogs/dart-tinctorius-cobalt.jpg"]', 5, 0),
  (18, 3, 'dart-golden-terribilis', 'Ếch Phi Tiêu Vàng Ánh Kim (Golden Poison Frog - CB)', 'Phyllobates terribilis', 'Yellow / Gold (Captive Bred)', 1950000, 2300000, 'Sub-adult (3.5 - 4cm)', '10 - 15 năm', 'Nâng cao', 'terrestrial', '22 - 26°C', '85 - 95%', 'Ruồi giấm lớn, dế pinhead, bọ cánh cứng nhỏ', 'Trong tự nhiên, đây là loài động vật có nọc độc mạnh nhất hành tinh; nhưng khi sinh sản nhân tạo (CB), chúng HOÀN TOÀN KHÔNG ĐỘC! Toàn thân ánh vàng kim loại rực rỡ, tính cách cực kỳ dạn dĩ, luôn đi dạo tự tin trước mặt bạn.', 'Bể terrarium lớn, thoáng khí, sức ăn khỏe hơn nhiều so với các loài phi tiêu khác.', 'Ếch CB F3 thuần dưỡng, không độc tố 100%, đực kêu râm ran vui tai', '/images/frogs/dart-golden-terribilis.jpg', '["/images/frogs/dart-golden-terribilis.jpg"]', 3, 0),
  (19, 3, 'dart-auratus-green-black', 'Ếch Phi Tiêu Xanh Đen Cẩm Thạch (Green and Black)', 'Dendrobates auratus', 'Costa Rica Green', 1150000, 1350000, 'Sub-adult (3cm)', '10 - 15 năm', 'Trung bình', 'terrestrial', '23 - 27°C', '80 - 90%', 'Ruồi giấm cánh cụt, bọ đuôi bật', 'Hoa văn vân cẩm thạch màu xanh ngọc lục bảo uốn lượn kỳ ảo trên nền đen bóng loáng. Là một trong những loài phi tiêu dễ nuôi, khỏe mạnh và thích nghi tốt nhất cho người mới bắt đầu chơi dòng phi tiêu.', 'Chuồng bán cạn rải lá mục, nhiều cây lá rộng để trú ẩn khi giật mình.', 'Màu xanh ngọc ánh kim sáng bóng, nhảy nhanh nhẹn', '/images/frogs/dart-auratus-green-black.jpg', '["/images/frogs/dart-auratus-green-black.jpg"]', 6, 0),
  (20, 4, 'bullfrog-pixie', 'Ếch Bò Yêu Tinh Châu Phi (Pixie Bullfrog)', 'Pyxicephalus adspersus', 'African Giant Classic', 750000, 890000, 'Baby (5cm)', '20 - 35 năm', 'Dễ', 'terrestrial', '24 - 29°C', '65 - 80%', 'Cá chép mồi, cá trê con, chuột bao tử, dế, gián dubia', 'Gã khổng lồ của thế giới lưỡng cư! Khi trưởng thành có thể nặng tới 1.5 - 2kg, to bằng chiếc đĩa ăn cơm. Hàm răng xương sắc nhọn, tính cách dũng mãnh và sức ăn vô hạn.', 'Khi còn baby nuôi hộp nhỏ lót mút xốp hoặc bùn chuyên dụng. Cung cấp khay nước nông để ngâm mình hàng ngày.', 'Cá thể đực tiềm năng vóc dáng lực lưỡng, đớp mồi như vũ bão', '/images/frogs/pixie-bullfrog.jpg', '["/images/frogs/pixie-bullfrog.jpg"]', 14, 0),
  (21, 4, 'bullfrog-budgetts', 'Ếch Ngoác Mồm Freddy Krueger (Budgett''s Frog)', 'Lepidobatrachus laevis', 'Wild Chaco Aquatic', 890000, 1050000, 'Sub-adult (5 - 6cm)', '10 - 15 năm', 'Trung bình', 'aquatic', '25 - 29°C', '80 - 95%', 'Cá mồi sống, trùn chỉ, tép sống, gián nhỏ rơi nước', 'Chú ếch nổi tiếng với biểu cảm hài hước đỉnh cao: thân hình dẹp lép như cái bánh bao, đôi mắt ti hí trên đỉnh đầu và chiếc miệng ngoác tận mang tai. Khi bị trêu chọc, chúng sẽ há to miệng và rít lên một tiếng the thé!', 'Sống gần như hoàn toàn dưới nước. Cần bể nước nông (10-15cm) có lọc nước êm và một bờ đá nổi để ngoi đầu thở.', 'Ăn cá mồi như chớp giật, miệng ngoác tròn xoe khỏe mạnh', '/images/frogs/bullfrog-budgetts.jpg', '["/images/frogs/bullfrog-budgetts.jpg"]', 7, 0),
  (22, 4, 'aquatic-african-clawed', 'Ếch Móng Vuốt Châu Phi (African Clawed Frog)', 'Xenopus laevis', 'Wild Olive Green', 220000, 280000, 'Sub-adult (5 - 6cm)', '15 - 25 năm', 'Dễ', 'aquatic', '20 - 26°C', '100%', 'Trùn chỉ, tim bò đông lạnh, cám viên chìm cho ếch thủy sinh', 'Loài ếch sống 100% hoàn toàn dưới nước như một chú cá cảnh! Chúng không có lưỡi và màng nhĩ, dùng hai tay trước lùa thức ăn vào miệng và có 3 móng vuốt đen nhỏ xíu ở chân sau.', 'Nuôi trong bể cá thông thường có lọc nước, sỏi lớn, không cần cạn.', 'Bơi lội tung tăng, ăn khỏe, không dị tật', '/images/frogs/aquatic-african-clawed.jpg', '["/images/frogs/aquatic-african-clawed.jpg"]', 15, 0),
  (23, 5, 'mossy-vietnamese', 'Ếch Rêu Việt Nam (Vietnamese Mossy Frog)', 'Theloderma corticale', 'Vietnamese Mossy Classic', 890000, 1050000, 'Sub-adult (4.5cm)', '8 - 12 năm', 'Trung bình', 'paludarium', '20 - 25°C', '80 - 95%', 'Dế nhỏ, sâu canxi, ruồi giấm, gián red runner', 'Niềm tự hào lưỡng cư Việt Nam nổi tiếng khắp cộng đồng bò sát thế giới! Toàn thân sần sùi như một cụm rêu rừng ẩm ướt nguyên sinh. Ban ngày thu mình giả rêu đá, ban đêm bơi lội leo trèo săn mồi.', 'Bể bán cạn nước mát (ưa nhiệt độ mát mẻ 20-25°C), có nhiều khúc lũa phủ rêu và vách đá ẩm.', 'Sinh sản nhân tạo, sức khỏe ổn định tuyệt đối, rêu lên xanh mướt', '/images/frogs/mossy-frog.jpg', '["/images/frogs/mossy-frog.jpg"]', 8, 1),
  (24, 5, 'tomato-madagascar', 'Ếch Cà Chua Madagascar (Tomato Frog)', 'Dyscophus guineti', 'Madagascar Tomato', 650000, 750000, 'Sub-adult (5 - 6cm)', '8 - 12 năm', 'Dễ', 'terrestrial', '22 - 27°C', '70 - 85%', 'Dế, sâu gạo, gián dubia vừa miệng', 'Cơ thể tròn ủng, múp míp với màu đỏ cam rực rỡ y như một quả cà chua chín mọng. Khi bị đe dọa, chúng tự phồng to thân hình như quả bóng bay ngộ nghĩnh.', 'Lót chuồng bằng chất nền giữ ẩm dày (mùn xơ dừa ẩm) để ếch đào hang trú ẩn, đặt máng nước nông để ngâm mình.', 'Ếch căng tròn mọng nước, ăn khỏe, phản xạ nhanh nhẹn', '/images/frogs/tomato-frog.jpg', '["/images/frogs/tomato-frog.jpg"]', 9, 0),
  (25, 5, 'fire-bellied-oriental', 'Cóc Tía Rừng Bụng Đỏ (Oriental Fire-Bellied)', 'Bombina orientalis', 'Oriental Fire-bellied', 190000, 230000, 'Sub-adult (4cm)', '12 - 15 năm', 'Dễ', 'paludarium', '18 - 25°C', '75 - 85%', 'Trùn quế, dế con, sâu canxi, gián nhỏ', 'Mặt lưng màu xanh lá cây đốm đen sần sùi ngụy trang, nhưng mặt bụng rực rỡ màu đỏ cam cảnh báo. Rất thích bơi lội, cực kỳ trâu bò và dễ nuôi trong bể nước nông.', 'Thiết kế bể 50% nước sạch và 50% cạn (đá cuội/lũa). Có lọc nước thác chảy êm.', 'Thích nghi khí hậu Việt Nam cực tốt, bơi lội nhanh nhẹn', '/images/frogs/fire-bellied-toad.jpg', '["/images/frogs/fire-bellied-toad.jpg"]', 22, 0),
  (26, 5, 'rain-frog-bush', 'Ếch Bụi Rậm Mặt Buồn (Bush Rain Frog)', 'Breviceps adspersus', 'Bush Rain Frog', 1200000, 1400000, 'Adult (4 - 5cm)', '6 - 10 năm', 'Trung bình', 'terrestrial', '20 - 26°C', '65 - 80%', 'Mối đất, dế con, sâu quy nhỏ, kiến đất', 'Chú ếch nổi tiếng mạng xã hội với khuôn mặt tròn xoe lúc nào cũng cau có hờn dỗi và đôi chân ngắn cũn cỡn. Tiếng kêu éc éc rít lên như đồ chơi cao su khiến ai xem cũng phì cười.', 'Thích đào hang dưới cát pha đất ẩm. Chỉ trồi lên mặt đất khi cảm nhận được độ ẩm mát mẻ sau cơn mưa.', 'Hàng tuyển độc lạ, nguyên vẹn không sứt móng, ăn tốt mồi sống', '/images/frogs/rain-frog.jpg', '["/images/frogs/rain-frog.jpg"]', 6, 0);

-- Frog Species Details (1-1 Full Herpetology Data & AI Knowledge)
INSERT INTO frog_species_details (
  product_id, family, genus, species, origin_region, natural_habitat,
  adult_size_male_cm, adult_size_female_cm, lifespan_years, activity_period,
  temperament, social_cohabitation, enclosure_type, min_tank_size,
  temp_day_min, temp_day_max, temp_night_min, temp_night_max,
  humidity_min, humidity_max, lighting_uvb, substrate_recommended,
  water_requirements, primary_diet_json, feeding_frequency, supplements_guide,
  handling_safety, toxicity_warning, common_health_issues, critical_warnings_json,
  ai_knowledge_snippet, ai_facts_json
) VALUES
  (1, 'Ceratophryidae', 'Ceratophrys', 'cranwelli', 'Vùng Chaco (Argentina, Bolivia, Brazil, Paraguay)', 'Thảm cỏ đầm lầy bán khô hạn, vùi mình dưới lớp bùn lá ẩm', 11.5, 15.0, '8 - 12 năm', 'nocturnal', 'aggressive', 'strictly_solitary', 'terrestrial', '30x30x20cm (Hộp 15-20L)', 24.0, 28.0, 20.0, 23.0, 70, 80, 'Khuyến khích dùng đèn UVB 2.0 nhẹ, chu kỳ 10-12h', 'Mút xốp vi sinh ngập nước 1/3 hoặc xơ dừa ẩm chuyên dụng khử trùng', 'Nước đã khử clo 100%, thay nước sạch cách ngày', '["Cá mồi nhỏ (cá trâm, cá bảy màu)", "Dế mèn", "Gián Dubia", "Sâu Canxi", "Cám Pac Attack"]', 'Ếch con (dưới 6cm): 2 ngày/lần (1-2 con dế/cá). Ếch trưởng thành: 5-7 ngày/lần.', 'Bổ sung bột Canxi + Vitamin D3 (rắc lên mồi 1 lần/tuần cho ếch non, 2 tuần/lần cho ếch lớn).', 'Hạn chế cầm nắm. Da lưỡng cư hấp thu trực tiếp độc tố và muối từ tay người.', 'Hoàn toàn không có độc tố da. Cẩn thận vết cắn vì hàm răng xương có lực đớp rất mạnh.', 'Hội chứng chuyển hóa xương (MBD) do thiếu Canxi/D3; Tắc ruột (Impaction) do nuốt phải sỏi dăm hoặc dị vật.', '["Tuyệt đối KHÔNG nuôi chung 2 con cùng chuồng (sẽ ăn thịt nhau ngay lập tức)", "Không lót nền bằng sỏi nhỏ, đá dăm sắc nhọn (dễ nuốt phải gây tử vong do tắc ruột)", "Không dùng nước máy trực tiếp chưa khử clo"]', '# SPECIES_PROFILE: Ếch Pacman Xanh (Green) (Ceratophrys cranwelli)
- Họ sinh học: Ceratophryidae | Chi: Ceratophrys | Loài: cranwelli
- Xuất xứ: Vùng Chaco (Argentina, Bolivia, Brazil, Paraguay) | Sinh cảnh: Thảm cỏ đầm lầy bán khô hạn, vùi mình dưới lớp bùn lá ẩm
- Kích thước: Đực 11.5cm, Cái 15.0cm | Tuổi thọ: 8 - 12 năm
- Vi khí hậu tối ưu: Ngày 24.0-28.0°C, Đêm 20.0-23.0°C, Độ ẩm 70-80%
- Môi trường chuồng: terrestrial (30x30x20cm (Hộp 15-20L)), nền: Mút xốp vi sinh ngập nước 1/3 hoặc xơ dừa ẩm chuyên dụng khử trùng
- Tập tính: nocturnal | Tính cách: aggressive | Nuôi chung: strictly_solitary
- Thức ăn chính: Cá mồi nhỏ (cá trâm, cá bảy màu), Dế mèn, Gián Dubia, Sâu Canxi, Cám Pac Attack
- Chế độ dinh dưỡng: Ếch con (dưới 6cm): 2 ngày/lần (1-2 con dế/cá). Ếch trưởng thành: 5-7 ngày/lần. (Bổ sung: Bổ sung bột Canxi + Vitamin D3 (rắc lên mồi 1 lần/tuần cho ếch non, 2 tuần/lần cho ếch lớn).)
- Cảnh báo an toàn: Hạn chế cầm nắm. Da lưỡng cư hấp thu trực tiếp độc tố và muối từ tay người. | Độc tính: Hoàn toàn không có độc tố da. Cẩn thận vết cắn vì hàm răng xương có lực đớp rất mạnh.
- Bệnh thường gặp: Hội chứng chuyển hóa xương (MBD) do thiếu Canxi/D3; Tắc ruột (Impaction) do nuốt phải sỏi dăm hoặc dị vật.
- Cấm kỵ cốt lõi: Tuyệt đối KHÔNG nuôi chung 2 con cùng chuồng (sẽ ăn thịt nhau ngay lập tức); Không lót nền bằng sỏi nhỏ, đá dăm sắc nhọn (dễ nuốt phải gây tử vong do tắc ruột); Không dùng nước máy trực tiếp chưa khử clo', '{"species_code": "pacman-green", "common_name_vi": "Ếch Pacman Xanh (Green)", "scientific_name": "Ceratophrys cranwelli", "family": "Ceratophryidae", "origin_region": "Vùng Chaco (Argentina, Bolivia, Brazil, Paraguay)", "natural_habitat": "Thảm cỏ đầm lầy bán khô hạn, vùi mình dưới lớp bùn lá ẩm", "temperature_range_celsius": {"day": [24.0, 28.0], "night": [20.0, 23.0]}, "humidity_range_pct": [70, 80], "adult_size_cm": {"male": 11.5, "female": 15.0}, "lifespan_years": "8 - 12 năm", "activity_period": "nocturnal", "temperament": "aggressive", "can_cohabitate": false, "enclosure_type": "terrestrial", "primary_diet": ["Cá mồi nhỏ (cá trâm, cá bảy màu)", "Dế mèn", "Gián Dubia", "Sâu Canxi", "Cám Pac Attack"], "uvb_recommended": true, "handling_tolerance": "Hạn chế cầm nắm. Da lưỡng cư hấp thu trực tiếp độc tố và muối từ tay người.", "is_toxic": true, "critical_rules": ["Tuyệt đối KHÔNG nuôi chung 2 con cùng chuồng (sẽ ăn thịt nhau ngay lập tức)", "Không lót nền bằng sỏi nhỏ, đá dăm sắc nhọn (dễ nuốt phải gây tử vong do tắc ruột)", "Không dùng nước máy trực tiếp chưa khử clo"]}'),
  (2, 'Ceratophryidae', 'Ceratophrys', 'cranwelli', 'Chaco (Argentina/Bolivia) - Đột biến nuôi nhốt F2', 'Vùng đất trũng Nam Mỹ, nuôi dưỡng trong môi trường terrarium kiểm soát', 11.0, 14.5, '8 - 12 năm', 'nocturnal', 'aggressive', 'strictly_solitary', 'terrestrial', '30x30x20cm', 24.0, 28.0, 21.0, 23.0, 70, 80, 'Không dùng đèn UVB cường độ mạnh; mắt bạch tạng nhạy cảm với ánh sáng chói', 'Mút xốp êm hoặc dớn ẩm sạch khử khuẩn', 'Nước RO hoặc nước máy đã sục khí khử clo 24h', '["Cá mồi", "Dế mèn phủ canxi", "Gián Dubia con", "Cám Pacman chuyên dụng"]', 'Baby 2-3 ngày/lần. Trưởng thành 5-7 ngày/lần.', 'Canxi không D3 hoặc D3 liều thấp mỗi tuần 1 lần.', 'Quan sát là chính, tránh chạm vào da nhạy cảm', 'Không độc', 'Kích ứng mắt nếu ánh sáng quá chói; MBD xương mềm.', '["Cấm để dưới ánh nắng mặt trời trực tiếp (hỏng giác mạc bạch tạng)", "Cấm nuôi chung với bất kỳ sinh vật nào khác", "Tránh cho ăn mồi quá to so với khoảng cách giữa 2 mắt"]', '# SPECIES_PROFILE: Ếch Pacman Vàng Bạch Tạng (Albino) (Ceratophrys cranwelli)
- Họ sinh học: Ceratophryidae | Chi: Ceratophrys | Loài: cranwelli
- Xuất xứ: Chaco (Argentina/Bolivia) - Đột biến nuôi nhốt F2 | Sinh cảnh: Vùng đất trũng Nam Mỹ, nuôi dưỡng trong môi trường terrarium kiểm soát
- Kích thước: Đực 11.0cm, Cái 14.5cm | Tuổi thọ: 8 - 12 năm
- Vi khí hậu tối ưu: Ngày 24.0-28.0°C, Đêm 21.0-23.0°C, Độ ẩm 70-80%
- Môi trường chuồng: terrestrial (30x30x20cm), nền: Mút xốp êm hoặc dớn ẩm sạch khử khuẩn
- Tập tính: nocturnal | Tính cách: aggressive | Nuôi chung: strictly_solitary
- Thức ăn chính: Cá mồi, Dế mèn phủ canxi, Gián Dubia con, Cám Pacman chuyên dụng
- Chế độ dinh dưỡng: Baby 2-3 ngày/lần. Trưởng thành 5-7 ngày/lần. (Bổ sung: Canxi không D3 hoặc D3 liều thấp mỗi tuần 1 lần.)
- Cảnh báo an toàn: Quan sát là chính, tránh chạm vào da nhạy cảm | Độc tính: Không độc
- Bệnh thường gặp: Kích ứng mắt nếu ánh sáng quá chói; MBD xương mềm.
- Cấm kỵ cốt lõi: Cấm để dưới ánh nắng mặt trời trực tiếp (hỏng giác mạc bạch tạng); Cấm nuôi chung với bất kỳ sinh vật nào khác; Tránh cho ăn mồi quá to so với khoảng cách giữa 2 mắt', '{"species_code": "pacman-albino", "common_name_vi": "Ếch Pacman Vàng Bạch Tạng (Albino)", "scientific_name": "Ceratophrys cranwelli", "family": "Ceratophryidae", "origin_region": "Chaco (Argentina/Bolivia) - Đột biến nuôi nhốt F2", "natural_habitat": "Vùng đất trũng Nam Mỹ, nuôi dưỡng trong môi trường terrarium kiểm soát", "temperature_range_celsius": {"day": [24.0, 28.0], "night": [21.0, 23.0]}, "humidity_range_pct": [70, 80], "adult_size_cm": {"male": 11.0, "female": 14.5}, "lifespan_years": "8 - 12 năm", "activity_period": "nocturnal", "temperament": "aggressive", "can_cohabitate": false, "enclosure_type": "terrestrial", "primary_diet": ["Cá mồi", "Dế mèn phủ canxi", "Gián Dubia con", "Cám Pacman chuyên dụng"], "uvb_recommended": true, "handling_tolerance": "Quan sát là chính, tránh chạm vào da nhạy cảm", "is_toxic": false, "critical_rules": ["Cấm để dưới ánh nắng mặt trời trực tiếp (hỏng giác mạc bạch tạng)", "Cấm nuôi chung với bất kỳ sinh vật nào khác", "Tránh cho ăn mồi quá to so với khoảng cách giữa 2 mắt"]}'),
